import ujson
valid_qids = set()
with open('repo/data/mydata_extracted/ColBERT/queries.tsv') as f:
    for line in f:
        if line.strip():
            qid = line.strip().split('\t')[0]
            valid_qids.add(int(qid))
out = open('repo/data/mydata_extracted/ColBERT/triplets.jsonl', 'w')
with open('repo/data/mydata_extracted/ColBERT/triplets.jsonl') as f:
    for line in f:
        if line.strip():
            try:
                t = ujson.loads(line)
                if isinstance(t['query'], int) and t['query'] in valid_qids:
                    out.write(ujson.dumps(t) + '\n')
            except Exception:
                continue
out.close()
EOF
